$warmherbs = [
    ['name'=>'Rou Gui','latin'=>'Cinnamomi Cortex','properties'=>$warmtext('Acrid, sweet; hot','Acre, dulce; caliente'),'channels'=>$warmtext('Heart, Kidney, Liver, Spleen','Corazón, Riñón, Hígado, Bazo'),'dose'=>'1.5–4.5 g; add late','identity'=>$warmtext('Steadily warms Ming Men and the Lower Jiao, leads floating Fire back to its source and warms Blood and channels.','Calienta de forma sostenida Ming Men y Jiao Inferior, devuelve Fuego flotante a su fuente y calienta Sangre y canales.'),'clue'=>$warmtext('Chronic Kidney-Yang deficiency with cold low back, weak legs, impotence or floating deficient Yang—not sudden collapse.','Deficiencia crónica de Yang de Riñón con espalda baja fría, piernas débiles, impotencia o Yang deficiente flotante—no colapso súbito.'),'memory'=>$warmtext('The cinnamon bark is the basement furnace: steady heat for the Ming Men foundation.','La corteza de canela es la caldera del sótano: calor sostenido para la base Ming Men.'),'unique'=>$warmtext('Yang figure 13.1 gives it 70 for warming Kidney: slower and steadier than Fu Zi, with the distinctive ability to guide Fire home.','La figura 13.1 de Yang le asigna 70 para calentar Riñón: más lenta y sostenida que Fu Zi, con capacidad distintiva de devolver Fuego a su origen.'),'caution'=>$warmtext('Avoid in blazing Fire, Yin deficiency with Heat, pregnancy or bleeding from Heat. Add late to preserve volatile oils.','Evitar en Fuego intenso, deficiencia de Yin con Calor, embarazo o sangrado por Calor. Añadir tarde para conservar aceites volátiles.'),'formulas'=>[]],
    ['name'=>'Fu Zi','latin'=>'Aconiti Lateralis Radix Praeparata','properties'=>$warmtext('Acrid; hot; toxic','Acre; caliente; tóxica'),'channels'=>$warmtext('Heart, Kidney, Spleen','Corazón, Riñón, Bazo'),'dose'=>$warmtext('3–15 g study range; prolonged pre-decoction','3–15 g como rango de estudio; predecocción prolongada'),'identity'=>$warmtext('Rapidly rescues devastated Yang, warms the Fire of the Gate of Life and dispels Cold-Damp pain through all twelve channels.','Rescata rápidamente Yang devastado, calienta Fuego de la Puerta de la Vida y expulsa dolor Frío-Humedad por los doce canales.'),'clue'=>$warmtext('Cold limbs, faint pulse, profuse sweating, diarrhea or shock-like Yang collapse; also deep Cold Bi pain.','Extremidades frías, pulso casi imperceptible, sudor profuso, diarrea o colapso de Yang tipo shock; también Bi profundo por Frío.'),'memory'=>$warmtext('Fu Zi is the emergency main breaker that sends heat through all twelve rooms.','Fu Zi es el interruptor principal de emergencia que envía calor a las doce habitaciones.'),'unique'=>$warmtext('Fastest rescue herb here; Yang gives it 90 for warming Kidney. It stimulates existing Yang rather than slowly building it.','Es el rescate más rápido del grupo; Yang le da 90 para calentar Riñón. Estimula Yang existente en vez de construirlo lentamente.'),'caution'=>$warmtext('Only authenticated, properly processed Fu Zi under qualified supervision. Prolonged decoction is essential; numbness, weakness, dizziness, nausea or arrhythmia requires emergency care.','Solo Fu Zi autenticada y debidamente procesada bajo supervisión profesional. La cocción prolongada es esencial; entumecimiento, debilidad, mareo, náusea o arritmia requiere urgencias.'),'formulas'=>[[26,'zhen-wu-tang','Zhen Wu Tang',$warmtext('chief','principal')],[31,'si-ni-tang','Si Ni Tang',$warmtext('chief','principal')]]],
    ['name'=>'Gan Jiang','latin'=>'Zingiberis Rhizoma','properties'=>$warmtext('Acrid; hot','Acre; caliente'),'channels'=>$warmtext('Heart, Lung, Spleen, Stomach','Corazón, Pulmón, Bazo, Estómago'),'dose'=>'3–12 g','identity'=>$warmtext('Strongly warms the Middle, rescues devastated Yang and warms the Lung to transform thin Cold fluids.','Calienta con fuerza Jiao Medio, rescata Yang devastado y calienta Pulmón para transformar líquidos claros por Frío.'),'clue'=>$warmtext('Cold abdominal pain, vomiting or watery diarrhea; or cold thin sputum and wheezing.','Dolor abdominal frío, vómito o diarrea acuosa; o esputo claro y fino con sibilancia.'),'memory'=>$warmtext('Dry ginger is the kitchen stove: it heats the Middle and dries the cold steam rising to the Lung.','El jengibre seco es la estufa de cocina: calienta el Medio y seca el vapor frío que asciende al Pulmón.'),'unique'=>$warmtext('Yang figure 13.3 ranks it 100 for warming Spleen. Compared with Fu Zi, it centers on Middle-Jiao Cold and Lung fluids.','La figura 13.3 de Yang la coloca en 100 para calentar Bazo. Frente a Fu Zi, se centra en Frío del Jiao Medio y líquidos de Pulmón.'),'caution'=>$warmtext('Avoid with Yin deficiency, Blood Heat, dry cough or pregnancy Heat. It is hot and drying.','Evitar con deficiencia de Yin, Calor en Sangre, tos seca o Calor en embarazo. Es caliente y secante.'),'formulas'=>[[28,'li-zhong-wan','Li Zhong Wan',$warmtext('chief','principal')]]],
    ['name'=>'Gao Liang Jiang','latin'=>'Alpiniae Officinarum Rhizoma','properties'=>$warmtext('Acrid; hot','Acre; caliente'),'channels'=>$warmtext('Spleen, Stomach','Bazo, Estómago'),'dose'=>'3–6 g','identity'=>$warmtext('Directly warms the Stomach, disperses Cold, stops pain and redirects rebellious Qi downward.','Calienta directamente Estómago, dispersa Frío, detiene dolor y redirige Qi rebelde hacia abajo.'),'clue'=>$warmtext('Sudden severe epigastric pain, nausea or vomiting relieved by warmth.','Dolor epigástrico súbito e intenso, náusea o vómito aliviado por calor.'),'memory'=>$warmtext('The galangal burner sits directly under the Stomach pot.','El quemador de galanga está directamente bajo la olla del Estómago.'),'unique'=>$warmtext('Yang figure 13.4 ranks it 100—the strongest Stomach warmer in that comparison.','La figura 13.4 de Yang la coloca en 100—la calentadora de Estómago más fuerte de esa comparación.'),'caution'=>$warmtext('Use only for true Cold; avoid with Stomach Fire, Yin deficiency or Heat vomiting.','Usar solo para Frío verdadero; evitar con Fuego de Estómago, deficiencia de Yin o vómito por Calor.'),'formulas'=>[]],
    ['name'=>'Pao Jiang','latin'=>'Zingiberis Rhizoma Praeparatum','properties'=>$warmtext('Bitter, astringent; warm','Amarga, astringente; tibia'),'channels'=>$warmtext('Spleen, Liver','Bazo, Hígado'),'dose'=>'3–6 g','identity'=>$warmtext('Warms the Middle gently, binds chronic diarrhea and stops bleeding from Spleen-Yang deficiency Cold.','Calienta suavemente el Medio, contiene diarrea crónica y detiene sangrado por Frío de deficiencia de Yang de Bazo.'),'clue'=>$warmtext('Chronic cold diarrhea or pale, thin bleeding with abdominal cold and weakness.','Diarrea fría crónica o sangrado pálido y fino con frío abdominal y debilidad.'),'memory'=>$warmtext('Prepared ginger is the banked ember: it stays, warms and seals leaks.','El jengibre preparado es la brasa cubierta: permanece, calienta y sella fugas.'),'unique'=>$warmtext('Yang gives it 60 for warming Spleen. It is less dispersing than Gan Jiang and more hemostatic and astringent.','Yang le asigna 60 para calentar Bazo. Es menos dispersante que Gan Jiang y más hemostática/astringente.'),'caution'=>$warmtext('Not for bleeding from Heat or with retained stasis; chronic or heavy bleeding needs medical assessment.','No usar para sangrado por Calor ni con estasis retenida; sangrado crónico o abundante requiere evaluación médica.'),'formulas'=>[]],
    ['name'=>'Cao Wu *','latin'=>'Aconiti Kusnezoffii Radix Praeparata','properties'=>$warmtext('Acrid, bitter; hot; very toxic','Acre, amarga; caliente; muy tóxica'),'channels'=>$warmtext('Heart, Liver, Kidney, Spleen','Corazón, Hígado, Riñón, Bazo'),'dose'=>$warmtext('1.5–3 g study range; prolonged pre-decoction','1.5–3 g como rango de estudio; predecocción prolongada'),'identity'=>$warmtext('Fiercely dispels Wind-Cold-Damp and relieves severe fixed Bi pain.','Expulsa con ferocidad Viento-Frío-Humedad y alivia dolor Bi fijo e intenso.'),'clue'=>$warmtext('Severe cold, fixed, penetrating joint or channel pain that resists gentler herbs.','Dolor intenso, frío, fijo y penetrante de articulaciones o canales que no responde a hierbas suaves.'),'memory'=>$warmtext('Cao Wu is a toxic blowtorch for frozen painful corridors—not a household heater.','Cao Wu es un soplete tóxico para corredores congelados y dolorosos—no un calentador doméstico.'),'unique'=>$warmtext('Pain-channel specialist with a narrower target and greater toxicity burden than Fu Zi. Yang’s 100-point Kidney figure names Wu Tou, not exact Cao Wu, so that value is not transferred.','Especialista en canales dolorosos con objetivo más estrecho y mayor carga tóxica que Fu Zi. La figura renal de 100 puntos de Yang nombra Wu Tou, no Cao Wu exacta; ese valor no se transfiere.'),'caution'=>$warmtext('Only properly processed product under expert supervision. Never self-dose; avoid pregnancy. Cardiac and neurologic toxicity can be fatal.','Solo producto debidamente procesado bajo supervisión experta. Nunca automedicarse; evitar en embarazo. La toxicidad cardíaca y neurológica puede ser mortal.'),'formulas'=>[[56,'xiao-huo-luo-dan','Xiao Huo Luo Dan',$warmtext('co-chief','coprincipal')]]],
    ['name'=>'Wu Zhu Yu','latin'=>'Evodiae Fructus','properties'=>$warmtext('Acrid, bitter; hot; slightly toxic','Acre, amarga; caliente; ligeramente tóxica'),'channels'=>$warmtext('Liver, Spleen, Stomach, Kidney','Hígado, Bazo, Estómago, Riñón'),'dose'=>'1.5–4.5 g','identity'=>$warmtext('Warms Liver and Stomach, redirects rebellious Qi, stops pain and dries Dampness.','Calienta Hígado y Estómago, redirige Qi rebelde, detiene dolor y seca Humedad.'),'clue'=>$warmtext('Jueyin vertex headache with dry heaves or vomiting of clear fluid; Cold Liver Qi may descend to hernia pain.','Cefalea de vértex Jueyin con arcadas o vómito de líquido claro; Qi frío de Hígado puede descender a dolor herniario.'),'memory'=>$warmtext('Evodia starts on the roof at the vertex and forces the rebellious elevator down.','Evodia comienza en el techo, en el vértex, y obliga al elevador rebelde a bajar.'),'unique'=>$warmtext('Yang figure 13.2 ranks it 100 for warming Liver—the clearest Liver-Cold plus rebellious-Stomach-Qi fingerprint.','La figura 13.2 de Yang la coloca en 100 para calentar Hígado—la huella más clara de Frío de Hígado más Qi rebelde de Estómago.'),'caution'=>$warmtext('Hot, drying and slightly toxic; avoid in Heat, Yin deficiency or vomiting from Stomach Fire. Use briefly and carefully.','Caliente, secante y ligeramente tóxica; evitar en Calor, deficiencia de Yin o vómito por Fuego de Estómago. Uso breve y cuidadoso.'),'formulas'=>[[29,'wu-zhu-yu-tang','Wu Zhu Yu Tang',$warmtext('chief','principal')],[47,'wen-jing-tang','Wen Jing Tang',$warmtext('co-chief','coprincipal')]]],
    ['name'=>'Xiao Hui Xiang','latin'=>'Foeniculi Fructus','properties'=>$warmtext('Acrid; warm','Acre; tibia'),'channels'=>$warmtext('Liver, Kidney, Spleen, Stomach','Hígado, Riñón, Bazo, Estómago'),'dose'=>'3–6 g','identity'=>$warmtext('Warms Liver and Kidney, disperses Lower-Jiao Cold, regulates Qi and harmonizes the Stomach.','Calienta Hígado y Riñón, dispersa Frío de Jiao Inferior, regula Qi y armoniza Estómago.'),'clue'=>$warmtext('Cold lower-abdominal or hernia pain with Qi stagnation; may include cold Stomach pain or vomiting.','Dolor frío de abdomen inferior o hernia con estancamiento de Qi; puede incluir dolor frío de Estómago o vómito.'),'memory'=>$warmtext('Fennel warms the lower gate and turns its aromatic key so Qi can move.','El hinojo calienta la puerta inferior y gira su llave aromática para mover Qi.'),'unique'=>$warmtext('Yang ranks it 80 for Liver warmth and 70 for both Spleen and Stomach—an aromatic bridge between Lower and Middle Jiao.','Yang le asigna 80 para calentar Hígado y 70 para Bazo y Estómago—un puente aromático entre Jiao Inferior y Medio.'),'caution'=>$warmtext('Avoid with Yin deficiency or Excess Heat; use cautiously in pregnancy unless professionally indicated.','Evitar con deficiencia de Yin o Calor de Exceso; precaución en embarazo salvo indicación profesional.'),'formulas'=>[]],
