$warmquestions = [
    [$warmtext('What are the functions and indications of herbs that warm the Interior?','¿Cuáles son las funciones e indicaciones de las hierbas que calientan el Interior?'),$warmtext('They dispel internal Cold, warm organs and channels, stop Cold pain and restore Yang. Board signs include severe aversion to cold, cold limbs, pale tongue with moist white coat, deep slow or weak pulse, clear fluids, watery stool, pain improved by warmth and weak or rebellious organ Qi.','Expulsan Frío interno, calientan órganos y canales, detienen dolor por Frío y restauran Yang. Pistas Board: frío intenso, extremidades frías, lengua pálida con capa blanca húmeda, pulso profundo lento o débil, líquidos claros, heces acuosas, dolor mejorado por calor y Qi orgánico débil o rebelde.')],
    [$warmtext('What are the characteristics and precautions of herbs that warm the Interior?','¿Cuáles son las características y precauciones de las hierbas que calientan el Interior?'),$warmtext('Most are acrid, hot, drying and moving. They can consume Yin, fluids and Blood or aggravate Heat and bleeding. Aconites require verified processing, prolonged decoction and expert supervision; pregnancy and mixed Heat patterns demand special caution.','La mayoría son acres, calientes, secantes y móviles. Pueden consumir Yin, líquidos y Sangre o agravar Calor y sangrado. Los acónitos requieren procesamiento verificado, cocción prolongada y supervisión experta; embarazo y patrones mixtos con Calor exigen cautela especial.')],
    [$warmtext('What is the difference between stimulating Yang and tonifying Yang?','¿Cuál es la diferencia entre estimular Yang y tonificar Yang?'),$warmtext('Fu Zi and Rou Gui rapidly activate and mobilize existing Yang and expel Cold; Yang-tonic herbs such as Lu Rong or Ba Ji Tian, outside this category, build deficient Yang more gradually. Rescue a collapse with stimulation; rebuild chronic deficiency with tonification after stabilization.','Fu Zi y Rou Gui activan y movilizan rápidamente Yang existente y expulsan Frío; tónicos de Yang como Lu Rong o Ba Ji Tian, fuera de esta categoría, construyen Yang deficiente gradualmente. El colapso se rescata estimulando; la deficiencia crónica se reconstruye tras estabilizar.')],
    [$warmtext('Which treatment strategies are used when warming the Interior?','¿Qué estrategias terapéuticas se usan al calentar el Interior?'),$warmtext('Match the site and urgency: rescue collapsed Yang; warm Kidney/Ming Men; warm Spleen-Stomach and redirect Qi; warm Lung and transform thin fluid; warm Liver and move Qi; warm channels for Bi pain; or warm and stop deficiency-Cold bleeding.','Ajusta sitio y urgencia: rescatar Yang colapsado; calentar Riñón/Ming Men; calentar Bazo-Estómago y redirigir Qi; calentar Pulmón y transformar líquidos claros; calentar Hígado y mover Qi; calentar canales para Bi; o calentar y detener sangrado por Frío-deficiencia.')],
    [$warmtext('What are the differences between Fu Zi and Rou Gui?','¿Cuáles son las diferencias entre Fu Zi y Rou Gui?'),$warmtext('Fu Zi is faster, more mobile and more toxic: it rescues devastated Yang and reaches all channels. Rou Gui is steadier, focuses on Ming Men and Lower Jiao, warms Blood and guides floating Fire back to its source.','Fu Zi es más rápida, móvil y tóxica: rescata Yang devastado y llega a todos los canales. Rou Gui es más sostenida, se enfoca en Ming Men/Jiao Inferior, calienta Sangre y devuelve Fuego flotante a su fuente.')],
    [$warmtext('What are the differences between Fu Zi and Gan Jiang?','¿Cuáles son las diferencias entre Fu Zi y Gan Jiang?'),$warmtext('Fu Zi restores Heart-Kidney Yang and circulation in systemic collapse. Gan Jiang centers on Spleen-Stomach Cold and also warms Lung fluid; together they reinforce rescue while protecting the Middle.','Fu Zi restaura Yang de Corazón-Riñón y circulación en colapso sistémico. Gan Jiang se centra en Frío de Bazo-Estómago y también calienta líquidos de Pulmón; juntas refuerzan rescate y protegen el Medio.')],
    [$warmtext('How do Sheng Jiang, Gan Jiang and Pao Jiang differ?','¿Cómo se diferencian Sheng Jiang, Gan Jiang y Pao Jiang?'),$warmtext('Sheng Jiang, outside this list, is fresh, mild and dispersing for Exterior Cold and nausea. Gan Jiang is dried, hot and strongly warms Middle and Lung. Pao Jiang is prepared, milder and staying: it warms, binds diarrhea and stops deficiency-Cold bleeding.','Sheng Jiang, fuera de lista, es fresca, suave y dispersante para Frío Exterior y náusea. Gan Jiang es seca, caliente y calienta con fuerza Medio y Pulmón. Pao Jiang es preparada, más suave y retenedora: calienta, contiene diarrea y detiene sangrado por Frío-deficiencia.')],
    [$warmtext('How do Fu Zi and Wu Tou differ?','¿Cómo se diferencian Fu Zi y Wu Tou?'),$warmtext('Fu Zi emphasizes Yang rescue and warming Heart-Kidney-Spleen. Wu Tou emphasizes severe Wind-Cold-Damp channel pain and is more toxic. The current list names Cao Wu, a related prepared aconite; it must not silently inherit every Wu Tou comparison value.','Fu Zi enfatiza rescate de Yang y calentamiento de Corazón-Riñón-Bazo. Wu Tou enfatiza dolor grave por Viento-Frío-Humedad y es más tóxica. La lista actual nombra Cao Wu, acónito preparado relacionado; no debe heredar silenciosamente todos los valores de Wu Tou.')],
    [$warmtext('What are the differences between Rou Gui and Gui Zhi?','¿Cuáles son las diferencias entre Rou Gui y Gui Zhi?'),$warmtext('Rou Gui is bark: hotter, deeper and focused on Ming Men, Lower Jiao and Blood. Gui Zhi, outside this list, is twig: lighter and more superficial, releasing the muscle layer and warming channels and Heart Yang.','Rou Gui es corteza: más caliente, profunda y enfocada en Ming Men, Jiao Inferior y Sangre. Gui Zhi, fuera de lista, es ramita: más ligera/superficial, libera capa muscular y calienta canales y Yang de Corazón.')],
    [$warmtext('How do Wu Zhu Yu, Gan Jiang and Fu Zi differ?','¿Cómo se diferencian Wu Zhu Yu, Gan Jiang y Fu Zi?'),$warmtext('Wu Zhu Yu warms Liver/Stomach and descends rebellious Qi—vertex headache and clear-fluid vomiting. Gan Jiang warms Spleen-Stomach and Lung. Fu Zi rescues systemic Heart-Kidney Yang and warms the entire channel network.','Wu Zhu Yu calienta Hígado/Estómago y desciende Qi rebelde—cefalea de vértex y vómito claro. Gan Jiang calienta Bazo-Estómago y Pulmón. Fu Zi rescata Yang sistémico de Corazón-Riñón y calienta toda la red de canales.')],
    [$warmtext('How do Rou Gui and Ai Ye differ?','¿Cómo se diferencian Rou Gui y Ai Ye?'),$warmtext('Rou Gui warms Ming Men, Blood and channels and treats broad interior Yang deficiency. Ai Ye, outside this list, is more specifically uterine and hemostatic for Lower-Jiao Cold bleeding and also calms the fetus or serves as moxa.','Rou Gui calienta Ming Men, Sangre y canales y trata deficiencia amplia de Yang interior. Ai Ye, fuera de lista, es más uterina/hemostática para sangrado por Frío de Jiao Inferior, calma feto y sirve como moxa.')],
    [$warmtext('How do Ai Ye and Pao Jiang differ?','¿Cómo se diferencian Ai Ye y Pao Jiang?'),$warmtext('Ai Ye, outside this list, treats Blood-level uterine/Lower-Jiao Cold bleeding. Pao Jiang focuses on Spleen-Yang deficiency in the Middle Jiao with chronic diarrhea or digestive bleeding.','Ai Ye, fuera de lista, trata sangrado por Frío en nivel Sangre uterino/Jiao Inferior. Pao Jiang se centra en deficiencia de Yang de Bazo en Jiao Medio con diarrea crónica o sangrado digestivo.')],
    [$warmtext('How do Sheng Jiang and Gao Liang Jiang differ?','¿Cómo se diferencian Sheng Jiang y Gao Liang Jiang?'),$warmtext('Sheng Jiang, outside this list, gently harmonizes the Stomach, stops nausea and releases Exterior Cold. Gao Liang Jiang is hotter and much stronger for true Stomach Cold with severe epigastric pain and vomiting.','Sheng Jiang, fuera de lista, armoniza suavemente Estómago, detiene náusea y libera Frío Exterior. Gao Liang Jiang es más caliente y mucho más fuerte para Frío verdadero de Estómago con dolor epigástrico intenso y vómito.')],
    [$warmtext('How does Xiao Hui Xiang differ from Cao Dou Kou, Hua Jiao and Ding Xiang?','¿Cómo se diferencia Xiao Hui Xiang de Cao Dou Kou, Hua Jiao y Ding Xiang?'),$warmtext('Xiao Hui Xiang warms Liver/Kidney and moves Qi for lower-abdominal or hernia pain while also harmonizing Stomach. Outside this list: Cao Dou Kou emphasizes Cold-Damp Middle obstruction, Hua Jiao warms and kills parasites, and Ding Xiang strongly descends Stomach Qi and assists Kidney Yang.','Xiao Hui Xiang calienta Hígado/Riñón y mueve Qi para dolor abdominal inferior o hernia, además armoniza Estómago. Fuera de lista: Cao Dou Kou trata obstrucción Frío-Humedad del Medio, Hua Jiao calienta y mata parásitos, y Ding Xiang desciende Qi de Estómago y ayuda Yang de Riñón.')],
    [$warmtext('Which herbs warm the Stomach and stop vomiting, and how are the current-list choices distinguished?','¿Qué hierbas calientan Estómago y detienen vómito, y cómo se distinguen las opciones de la lista actual?'),$warmtext('Gao Liang Jiang is strongest for direct Stomach Cold and pain. Wu Zhu Yu adds Liver-Cold, vertex headache and rebellious clear-fluid vomiting. Gan Jiang adds Spleen deficiency and watery diarrhea. Xiao Hui Xiang adds lower-abdominal Qi stagnation or hernia. Several other herbs in Yang’s answer are outside this list.','Gao Liang Jiang es la más fuerte para Frío directo de Estómago y dolor. Wu Zhu Yu añade Frío de Hígado, vértex y vómito rebelde claro. Gan Jiang añade deficiencia de Bazo y diarrea acuosa. Xiao Hui Xiang añade estancamiento de Qi inferior o hernia. Otras hierbas de Yang están fuera de lista.')],
];
?>

<section class="single-herbs-guide__section" aria-labelledby="topic-twentyone-foundations"><h4 id="topic-twentyone-foundations"><?php echo s($warmtext('Warm the Interior and expel Cold: general introduction','Calentar el Interior y expulsar Frío: introducción general'));?></h4><p class="single-herbs-guide__section-lead"><?php echo s($warmtext('The first Board decision is urgency: sudden Yang collapse needs rescue; chronic deficiency needs steady warming; localized Cold needs the herb whose organ and direction match the presentation.','La primera decisión Board es la urgencia: colapso súbito de Yang necesita rescate; deficiencia crónica necesita calor sostenido; Frío localizado necesita la hierba cuyo órgano y dirección coincidan.'));?></p><p class="single-herbs-guide__scope-note"><strong><?php echo s($warmtext('Name normalization:','Normalización de nombres:'));?></strong> <?php echo s($warmtext('The supplied “Gao Jiang” is presented as standard Gan Jiang, and “Xiao Hu Xiang” as standard Xiao Hui Xiang. Gao Liang Jiang remains a separate herb.','“Gao Jiang” del listado se presenta como Gan Jiang estándar, y “Xiao Hu Xiang” como Xiao Hui Xiang estándar. Gao Liang Jiang permanece como hierba distinta.'));?></p><div class="single-herbs-guide__decision"><div><strong><?php echo s($warmtext('Yang collapse','Colapso de Yang'));?></strong><span>Fu Zi · Gan Jiang</span></div><div><strong><?php echo s($warmtext('Kidney / Ming Men','Riñón / Ming Men'));?></strong><span>Rou Gui · Fu Zi</span></div><div><strong><?php echo s($warmtext('Middle / Stomach','Medio / Estómago'));?></strong><span>Gan Jiang · Gao Liang Jiang · Pao Jiang</span></div><div><strong><?php echo s($warmtext('Liver / channels','Hígado / canales'));?></strong><span>Wu Zhu Yu · Xiao Hui Xiang · Cao Wu</span></div></div><aside class="single-herbs-guide__memory-path"><p class="single-herbs-guide__memory-line"><?php echo s($warmtext('Enter the Interior furnace house.','Entra a la casa-caldera del Interior.'));?></p><p><?php echo s($warmtext('Fu Zi flips the emergency main breaker; Rou Gui tends the basement Ming-Men furnace. Gan Jiang heats the kitchen and Gao Liang Jiang the Stomach burner. Pao Jiang banks an ember to seal leaks. Cao Wu is the toxic blowtorch for frozen painful corridors. Wu Zhu Yu starts at the vertex roof and drives the elevator down. Xiao Hui Xiang warms the lower gate and turns the Qi key.','Fu Zi activa el interruptor de emergencia; Rou Gui cuida la caldera Ming Men del sótano. Gan Jiang calienta cocina y Gao Liang Jiang el quemador del Estómago. Pao Jiang cubre una brasa para sellar fugas. Cao Wu es el soplete tóxico de corredores dolorosos congelados. Wu Zhu Yu parte del techo-vértex y baja el elevador. Xiao Hui Xiang calienta la puerta inferior y gira la llave del Qi.'));?></p></aside><p class="single-herbs-guide__safety"><strong><?php echo s($warmtext('Aconite safety boundary:','Límite de seguridad de acónitos:'));?></strong> <?php echo s($warmtext('Fu Zi and Cao Wu are toxic medicines, not self-treatment herbs. Exact identity, processing, dose, decoction and interactions require qualified professional control. Suspected toxicity is an emergency.','Fu Zi y Cao Wu son medicinas tóxicas, no hierbas de autotratamiento. Identidad, procesamiento, dosis, cocción e interacciones requieren control profesional. Sospecha de toxicidad es una emergencia.'));?></p><ol class="single-herbs-guide__category-herbs"><?php foreach($warmherbs as $h):?><li class="single-herbs-guide__category-herb single-herbs-guide__category-herb--core"><div class="single-herbs-guide__category-herb-head"><strong><?php echo s($h['name']);?></strong><em><?php echo s($h['latin']);?></em><span class="single-herbs-guide__category-herb-badge"><?php echo s($warmtext('Current category list','Lista vigente de la categoría'));?></span></div><p><?php echo s($h['identity']);?></p></li><?php endforeach;?></ol></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-twentyone-yang"><h4 id="topic-twentyone-yang"><?php echo s($warmtext('Yang comparative fingerprints','Huellas comparativas de Yang'));?></h4><p class="single-herbs-guide__section-lead"><?php echo s($warmtext('Relative study indices from Yang—not doses, efficacy percentages or permission to substitute related aconites. Only exact current-list entries are graphed.','Índices relativos de estudio de Yang—no dosis, porcentajes de eficacia ni permiso para sustituir acónitos relacionados. Solo se grafican entradas exactas de la lista actual.'));?></p><div class="single-herbs-guide__yang-charts"><?php foreach($warmcharts as $chart):?><article class="single-herbs-guide__yang-chart"><h5><?php echo s($chart[0]);?></h5><small><?php echo s($chart[1]);?></small><?php foreach($chart[2] as $name=>$value):?><div class="single-herbs-guide__yang-bar"><span><?php echo s($name);?></span><span class="single-herbs-guide__yang-bar-track"><span class="single-herbs-guide__yang-bar-fill" style="width:<?php echo(int)$value;?>%"></span></span><b><?php echo(int)$value;?></b></div><?php endforeach;?></article><?php endforeach;?></div><p class="single-herbs-guide__yang-note"><strong><?php echo s($warmtext('Exact-name boundary:','Límite de nombre exacto:'));?></strong> <?php echo s($warmtext('Yang figure 13.1 gives Wu Tou 100, but the current list gives Cao Wu. Because related aconites are not interchangeable, Cao Wu is not assigned that bar. Other figure herbs outside this list are also omitted.','La figura 13.1 de Yang asigna 100 a Wu Tou, pero la lista actual dice Cao Wu. Como acónitos relacionados no son intercambiables, no se asigna esa barra a Cao Wu. También se omiten las demás hierbas fuera de lista.'));?></p></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-twentyone-profiles"><h4 id="topic-twentyone-profiles"><?php echo s($warmtext('Individual herb profiles','Perfiles individuales de las hierbas'));?></h4><div class="single-herbs-guide__profiles"><?php foreach($warmherbs as $h):?><details class="single-herbs-guide__profile"<?php echo $h['name']==='Fu Zi'?' open':'';?>><summary><span class="single-herbs-guide__profile-name"><?php echo s($h['name']);?></span><span class="single-herbs-guide__profile-latin"><?php echo s($h['latin']);?></span><span class="single-herbs-guide__profile-meta"><?php echo s($h['properties']);?> · <?php echo s($h['channels']);?></span></summary><div class="single-herbs-guide__profile-body"><dl><dt><?php echo s($warmtext('Study dose','Dosis de estudio'));?></dt><dd><?php echo s($h['dose']);?></dd><dt><?php echo s($warmtext('Identity','Identidad'));?></dt><dd><?php echo s($h['identity']);?></dd><dt><?php echo s($warmtext('Exam clue','Pista de examen'));?></dt><dd><?php echo s($h['clue']);?></dd><dt><?php echo s($warmtext('Memory','Memoria'));?></dt><dd class="single-herbs-guide__profile-memory"><?php echo s($h['memory']);?></dd><dt><?php echo s($warmtext('Unique fingerprint','Huella única'));?></dt><dd><?php echo s($h['unique']);?></dd><dt><?php echo s($warmtext('Formula boundary','Límite de fórmulas'));?></dt><dd class="single-herbs-guide__profile-formulas"><?php if($h['formulas']):foreach($h['formulas'] as $i=>$formula):?><?php if($i):?> · <?php endif;?><?php $path='/study-guide/comparisons/formula-navigator-'.sprintf('%02d',$formula[0]).'-'.$formula[1].($ises?'-es':'').'.html';$url=new moodle_url($path,['from'=>'single-herbs','focus'=>(string)$selected['number']]);?><a href="<?php echo $url->out(false);?>"><strong><?php echo s($formula[2]);?></strong></a> (<?php echo s($formula[3]);?>)<?php endforeach;?> — <?php echo s($warmtext('current 63-formula roster.','listado vigente de 63 fórmulas.'));?><?php else:echo s($warmtext('No chief or co-chief role in the current 63-formula Board roster.','No tiene papel principal ni coprincipal en el listado Board vigente de 63 fórmulas.'));endif;?></dd><dt><?php echo s($warmtext('Safety','Seguridad'));?></dt><dd class="single-herbs-guide__profile-safety"><?php echo s($h['caution']);?></dd></dl></div></details><?php endforeach;?></div></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-twentyone-comparisons"><h4 id="topic-twentyone-comparisons"><?php echo s($warmtext('High-yield comparisons','Comparaciones de alto rendimiento'));?></h4><div class="single-herbs-guide__comparisons"><?php foreach($warmcomparisons as $c):?><?php $url=new moodle_url($ises?$c[1]:$c[0],['from'=>'single-herbs','focus'=>(string)$selected['number']]);?><a class="single-herbs-guide__comparison" href="<?php echo $url->out(false);?>"><strong><?php echo s($c[2]);?></strong><span><?php echo s($c[3]);?></span><small><?php echo s($warmtext('Open full comparison →','Abrir comparación completa →'));?></small></a><?php endforeach;?></div></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-twentyone-questions"><h4 id="topic-twentyone-questions"><?php echo s($warmtext('Yang questions shown in full','Preguntas de Yang mostradas completas'));?></h4><p class="single-herbs-guide__section-lead"><?php echo s($warmtext('All fifteen Chapter 13 question topics that touch this list appear on the card fronts. Outside-list herbs are identified in the answers.','Los quince temas de preguntas del capítulo 13 que tocan esta lista aparecen al frente. Las hierbas fuera de lista se identifican en las respuestas.'));?></p><div class="single-herbs-guide__yang-deck" data-yang-deck data-card-label="<?php echo s($warmtext('Card','Tarjeta'));?>" data-of-label="<?php echo s($warmtext('of','de'));?>"><?php foreach($warmquestions as $i=>$q):?><article class="single-herbs-guide__yang-card<?php echo $i===0?' is-active':'';?>" data-yang-card aria-hidden="<?php echo $i===0?'false':'true';?>"><div class="single-herbs-guide__yang-face single-herbs-guide__yang-face--front"><span class="single-herbs-guide__yang-label"><?php echo s($warmtext('Question','Pregunta'));?> <?php echo$i+1;?> <?php echo s($warmtext('of','de'));?> <?php echo count($warmquestions);?> · Yang, <?php echo s($warmtext('Chapter','capítulo'));?> 13</span><p class="single-herbs-guide__yang-question"><?php echo s($q[0]);?></p></div><div class="single-herbs-guide__yang-face single-herbs-guide__yang-face--back"><span class="single-herbs-guide__yang-label"><?php echo s($warmtext('Answer','Respuesta'));?> <?php echo$i+1;?></span><p class="single-herbs-guide__yang-answer"><?php echo s($q[1]);?></p></div></article><?php endforeach;?><div class="single-herbs-guide__yang-controls"><button class="single-herbs-guide__yang-control" type="button" data-yang-prev>← <?php echo s($warmtext('Previous','Anterior'));?></button><button class="single-herbs-guide__yang-control single-herbs-guide__yang-control--flip" type="button" data-yang-flip data-show-label="<?php echo s($warmtext('Show answer','Mostrar respuesta'));?>" data-hide-label="<?php echo s($warmtext('Show question','Mostrar pregunta'));?>"><?php echo s($warmtext('Show answer','Mostrar respuesta'));?></button><button class="single-herbs-guide__yang-control single-herbs-guide__yang-control--next" type="button" data-yang-next><?php echo s($warmtext('Next','Siguiente'));?> →</button></div><p class="single-herbs-guide__yang-progress" data-yang-progress><?php echo s($warmtext('Card','Tarjeta'));?> 1 <?php echo s($warmtext('of','de'));?> <?php echo count($warmquestions);?></p></div></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-twentyone-recall"><h4 id="topic-twentyone-recall"><?php echo s($warmtext('Quick recall','Repaso rápido'));?></h4><div class="single-herbs-guide__recall"><details><summary><?php echo s($warmtext('Emergency Yang collapse versus steady Ming-Men deficiency?','¿Colapso urgente de Yang frente a deficiencia sostenida de Ming Men?'));?></summary><p><strong>Fu Zi</strong> / <strong>Rou Gui.</strong></p></details><details><summary><?php echo s($warmtext('Strongest Stomach warmer in Yang figure 13.4?','¿Calentadora de Estómago más fuerte en figura 13.4?'));?></summary><p><strong>Gao Liang Jiang.</strong></p></details><details><summary><?php echo s($warmtext('Vertex headache plus clear-fluid vomiting?','¿Cefalea de vértex más vómito de líquido claro?'));?></summary><p><strong>Wu Zhu Yu.</strong></p></details><details><summary><?php echo s($warmtext('Prepared ginger that warms and stops deficiency-Cold bleeding?','¿Jengibre preparado que calienta y detiene sangrado por Frío-deficiencia?'));?></summary><p><strong>Pao Jiang.</strong></p></details><details><summary><?php echo s($warmtext('Cold hernia/lower-abdominal pain plus Qi stagnation?','¿Hernia/dolor abdominal inferior frío más estancamiento de Qi?'));?></summary><p><strong>Xiao Hui Xiang.</strong></p></details><details><summary><?php echo s($warmtext('Toxic blowtorch for severe fixed Wind-Cold-Damp Bi pain?','¿Soplete tóxico para dolor Bi fijo e intenso por Viento-Frío-Humedad?'));?></summary><p><strong>Cao Wu.</strong></p></details></div></section>

